void dsky_mode_admit_input(apollo_overlay_state *s,p66_bias_io *io,uint16_t n){static const uint16_t raw[]={0,077777,037777,040000,0100000,0177777,0140000,1},caller[]={0100,0155,01777,02000,03455,04631,04675,07777};uint16_t cm=(uint16_t)(n>=4096u),j=(uint16_t)(n%4096u),cores=cm ? 7u : 8u,count=(uint16_t)(1u+(j/32u)%cores),i;p66_bias_prepare(s,n);s->words[3]=(uint16_t)((j/8u)%8u*0400u);s->words[4]=010000;s->words[6]=(uint16_t)(010000u|(s->words[3]>>8));s->words[5]=cm ? 02566u : 02636u;s->words[0]=raw[(j/32u)%8u];s->words[1]=raw[(j/64u)%8u];s->words[2]=caller[(j/128u)%8u];s->words[0167]=030123;s->words[067]=(uint16_t)((j/4u)%2u ? 077777u : (j/16u)%cores*12u);for(i=1;i<cores;++i)s->words[0167u+12u*i]=i<count ? (uint16_t)((j%3u ? 010000u+i : 077776u-i)) : 077777u;for(i=0;i<5u;++i)s->words[0400u+i*44u]=i<(j/32u)%6u ? (uint16_t)(0400u+i*44u) : 0;io->superbank=(uint16_t)((j/256u)%8u*020u);io->interrupt_enabled=(uint16_t)((j/128u)%2u);}
